CREATE OR REPLACE FUNCTION registry_context.evaluation_date()
              RETURNS date
              LANGUAGE sql
              STABLE
              SECURITY INVOKER
              AS $breg_function$
                  SELECT NULLIF(current_setting('registry.evaluation_date', true), '')::date
              $breg_function$;
